import{_ as e,o as l,c as a,a0 as s}from"./chunks/framework.DqMqoJl9.js";const b=JSON.parse('{"title":"进程管理","description":"","frontmatter":{},"headers":[],"relativePath":"linux/process.md","filePath":"linux/process.md","lastUpdated":1791039142000}'),n={name:"linux/process.md"};function i(d,t,r,o,p,c){return l(),a("div",null,[...t[0]||(t[0]=[s(`<h1 id="进程管理" tabindex="-1">进程管理 <a class="header-anchor" href="#进程管理" aria-label="Permalink to &quot;进程管理&quot;">​</a></h1><p>进程是正在执行的一个程序或命令，每一个进程都是一个运行的实体，都有自己的地址空间，并占用一定的系统资源</p><h4 id="进程管理-1" tabindex="-1">进程管理 <a class="header-anchor" href="#进程管理-1" aria-label="Permalink to &quot;进程管理&quot;">​</a></h4><ul><li>判断服务器的健康状态</li><li>查看系统中的所有进程</li><li>杀死进程</li></ul><h2 id="查看所有进程" tabindex="-1">查看所有进程 <a class="header-anchor" href="#查看所有进程" aria-label="Permalink to &quot;查看所有进程&quot;">​</a></h2><h3 id="ps" tabindex="-1">ps <a class="header-anchor" href="#ps" aria-label="Permalink to &quot;ps&quot;">​</a></h3><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">ps aux          </span><span style="color:#6A737D;">// 查看系统中所有进程，使用BSD操作系统格式</span></span>
<span class="line"><span style="color:#24292E;">ps </span><span style="color:#D73A49;">-</span><span style="color:#24292E;">le          </span><span style="color:#6A737D;">// 查看系统中所有进程，使用Linux标准命令格式</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>选项</p><ul><li><code>a</code> 显示一个终端的所有进程，出来会话引线</li><li><code>u</code> 显示进程的归属用户及内存的使用情况</li><li><code>x</code> 显示没有控制终端的进程</li><li><code>-l</code> 长格式显示，显示更加详细的信息</li><li><code>-e</code> 显示所有进程，和-A作用一致</li></ul><p>命令输出</p><ul><li><code>USER</code> 该进程是由哪个用户产生的</li><li><code>PID</code> 进程的ID号</li><li><code>%CPU</code> 该进程占用CPU资源的百分比</li><li><code>%MEM</code> 该进程占用物理内存的百分比</li><li><code>VSZ</code> 该进程占用虚拟内存的大小，单位KB</li><li><code>RSS</code> 该进程占用实际物理内存的大小，单位KB</li><li><code>TTY</code> 该进程是在哪个终端中运行的。其中tty1-tty7代表本地控制台终端，tty1-tty6是本地的字符界面终端，tty7是图形终端。pts/0-255代表虚拟终端</li><li><code>STAT</code> 该程状态 <ul><li><code>R</code> 运行</li><li><code>S</code> 睡眠</li><li><code>T</code> 停止状态</li><li><code>s</code> 包含子进程</li><li><code>+</code> 位于后台</li></ul></li><li><code>START</code> 该进程的启动时间</li><li><code>TIME</code> 该进程占用CPU的运算时间，注意不是系统时间</li><li><code>COMMAND</code> 产生此进程的命令名</li></ul><h3 id="pstree" tabindex="-1">pstree <a class="header-anchor" href="#pstree" aria-label="Permalink to &quot;pstree&quot;">​</a></h3><p>查看进程树</p><div class="language-txt line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span>pstree [选项]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>选项</p><ul><li><code>-p</code> 显示进程的PID</li><li><code>-u</code> 显示进程的所属用户</li></ul><h2 id="查看系统状态" tabindex="-1">查看系统状态 <a class="header-anchor" href="#查看系统状态" aria-label="Permalink to &quot;查看系统状态&quot;">​</a></h2><p>实时查看系统状态，3秒刷新一次</p><div class="language-txt line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span>top [选项]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>选项</p><ul><li><code>-d</code> 秒数，指定top命令每隔几秒更新。默认是3秒</li><li><code>-b</code> 使用批处理模式输出。一般和 &quot;-n&quot; 选项合用</li><li><code>-n</code> 次数，指定top命令执行的次数。一般和 &quot;-b&quot; 选项合用</li></ul><p>在top命令的交互模式中可以执行的命令：</p><ul><li><code>?或h</code> 显示交互模式的帮助</li><li><code>P</code> 以CPU使用率排序，默认就是此项</li><li><code>M</code> 以内存使用率排序</li><li><code>N</code> 以PID排序</li><li><code>q</code> 退出top</li></ul><p>top命令显示内容</p><table tabindex="0"><thead><tr><th style="text-align:left;"><div style="width:187px;">内容</div></th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;">12:23:46</td><td style="text-align:left;">系统当前时间</td></tr><tr><td style="text-align:left;">up 1 day, 13:32</td><td style="text-align:left;">系统的运行时间，本机已运行1天13小时32分钟</td></tr><tr><td style="text-align:left;">2 users</td><td style="text-align:left;">当前登录了两个用户</td></tr><tr><td style="text-align:left;">load average: 0.00 0.00 0.00</td><td style="text-align:left;">系统在之前1分钟、5分钟、15分钟的平均负载。一般认为小于1时，负载较小。如果大于1，系统已经超出负荷</td></tr><tr><td style="text-align:left;">Tasks: 95 total</td><td style="text-align:left;">系统中的进程总数</td></tr><tr><td style="text-align:left;">1 running</td><td style="text-align:left;">正在运行的进程数</td></tr><tr><td style="text-align:left;">94 sleeping</td><td style="text-align:left;">睡眠的进程</td></tr><tr><td style="text-align:left;">0 stopped</td><td style="text-align:left;">正在停止的进程</td></tr><tr><td style="text-align:left;">0 zombie</td><td style="text-align:left;">僵尸进程，即卡死的进程</td></tr><tr><td style="text-align:left;">Cpu(s): 0.1%us</td><td style="text-align:left;">用户欧式占用的CPU百分比</td></tr><tr><td style="text-align:left;">0.1%sy</td><td style="text-align:left;">系统模式占用的CPU百分比</td></tr><tr><td style="text-align:left;">0.0%ni</td><td style="text-align:left;">改变过优先级的用户进程占用的CPU百分比</td></tr><tr><td style="text-align:left;">99.7%id</td><td style="text-align:left;">空闲CPU的百分比</td></tr><tr><td style="text-align:left;">0.1%wa</td><td style="text-align:left;">等待输入/输出的进程的占用CPU百分比</td></tr><tr><td style="text-align:left;">0.0%hi</td><td style="text-align:left;">硬中断请求服务占用的CPU百分比</td></tr><tr><td style="text-align:left;">0.1%si</td><td style="text-align:left;">软中断请求服务占用的CPU百分比</td></tr><tr><td style="text-align:left;">0.0%st</td><td style="text-align:left;">st(steal time)虚拟时间百分比。就是当有虚拟机时，虚拟CPU等待实际CPU的时间百分比</td></tr><tr><td style="text-align:left;">Mem: 625344k total</td><td style="text-align:left;">物理内存的总量，单位KB</td></tr><tr><td style="text-align:left;">57150k used</td><td style="text-align:left;">已经使用的物理内存数量</td></tr><tr><td style="text-align:left;">53840k free</td><td style="text-align:left;">空闲的物理内存数量</td></tr><tr><td style="text-align:left;">65800k buffers</td><td style="text-align:left;">作为缓冲的内存数量</td></tr><tr><td style="text-align:left;">Swap: 524280k total</td><td style="text-align:left;">交换分区（虚拟内存）的总大小</td></tr><tr><td style="text-align:left;">0k used</td><td style="text-align:left;">已经使用的交互分区的大小</td></tr><tr><td style="text-align:left;">524280k free</td><td style="text-align:left;">空闲交换分区的大小</td></tr><tr><td style="text-align:left;">409280k cached</td><td style="text-align:left;">作为缓存的交互分区的大小</td></tr></tbody></table><h2 id="杀死进程" tabindex="-1">杀死进程 <a class="header-anchor" href="#杀死进程" aria-label="Permalink to &quot;杀死进程&quot;">​</a></h2><p>注意：程序都有正常关闭的方式，只有无法正常关闭时才需要杀死进程</p><h3 id="进程信号" tabindex="-1">进程信号 <a class="header-anchor" href="#进程信号" aria-label="Permalink to &quot;进程信号&quot;">​</a></h3><p>常用进程信号</p><table tabindex="0"><thead><tr><th style="text-align:left;">信号代号</th><th style="text-align:left;">信号名称</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;">1</td><td style="text-align:left;">SIGHUP</td><td style="text-align:left;">该信号让进程立即关闭，然后重新读取配置文件后重启</td></tr><tr><td style="text-align:left;">2</td><td style="text-align:left;">SIGINT</td><td style="text-align:left;">程序终止信号，用于终止前台进程。相当于输出 ctrl+c 快捷键</td></tr><tr><td style="text-align:left;">8</td><td style="text-align:left;">SIGFPE</td><td style="text-align:left;">在发生致命的算术运算错误时发出，不仅包括浮点运算错误，还包括溢出及除数为0等其它所有的算术的错误</td></tr><tr><td style="text-align:left;">9</td><td style="text-align:left;">SIGKILL</td><td style="text-align:left;">用来立即结束程序的运行，本信号不能被阻塞、处理和忽略。一般用于强制终止进程</td></tr><tr><td style="text-align:left;">14</td><td style="text-align:left;">SIGALRM</td><td style="text-align:left;">时钟定时信号，计算的是实际的时间或时钟时间，alarm函数使用该信号</td></tr><tr><td style="text-align:left;">15</td><td style="text-align:left;">SIGTERM</td><td style="text-align:left;">正常结束进程的信号，kill 命令的默认信号</td></tr><tr><td style="text-align:left;">18</td><td style="text-align:left;">SIGCONT</td><td style="text-align:left;">该信号可以让暂停的进程恢复执行，本信号不能被阻断</td></tr><tr><td style="text-align:left;">19</td><td style="text-align:left;">SIGSTOP</td><td style="text-align:left;">该信号可以暂停前台进程，相当于输入ctrl+z快捷键。本信号不能被阻断</td></tr></tbody></table><h3 id="kill" tabindex="-1">kill <a class="header-anchor" href="#kill" aria-label="Permalink to &quot;kill&quot;">​</a></h3><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">kill </span><span style="color:#D73A49;">-</span><span style="color:#24292E;">l         </span><span style="color:#6A737D;">// 查看可用的进程信号</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="pkill" tabindex="-1">pkill <a class="header-anchor" href="#pkill" aria-label="Permalink to &quot;pkill&quot;">​</a></h3><p>按照进程名终止进程</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">pkill [选项] [信号] 进程名</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>选项：</p><ul><li><code>-t</code> 终端号：按照终端号踢出用户</li></ul><h3 id="killall" tabindex="-1">killall <a class="header-anchor" href="#killall" aria-label="Permalink to &quot;killall&quot;">​</a></h3><p>按照进程名终止进程</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">pkill [选项] [信号] 进程名</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>选项：</p><ul><li><code>-i</code> 交互式，询问是否要杀死某个进程</li><li><code>-I</code> 忽略进程名的大小写</li></ul><h2 id="按终端号踢出用户" tabindex="-1">按终端号踢出用户 <a class="header-anchor" href="#按终端号踢出用户" aria-label="Permalink to &quot;按终端号踢出用户&quot;">​</a></h2><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#6F42C1;">w</span></span>
<span class="line"><span style="color:#6A737D;"># 使用w命令查询本机已登录的用户</span></span>
<span class="line"></span>
<span class="line"><span style="color:#6F42C1;">pkill</span><span style="color:#005CC5;"> -9</span><span style="color:#005CC5;"> -t</span><span style="color:#032F62;"> pts/1</span></span>
<span class="line"><span style="color:#6A737D;"># 强制杀死从 pts/1 虚拟终端登录的进程</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h2 id="工作管理" tabindex="-1">工作管理 <a class="header-anchor" href="#工作管理" aria-label="Permalink to &quot;工作管理&quot;">​</a></h2><p>工作管理指的是在单个登录终端中（也就是登录的shell界面中）同时管理多个工作的行为</p><h4 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h4><ul><li>当前的登录终端，只能管理当前终端的工作，而不能管理其他登录终端的工作</li><li>放入后台的命令必须可以持续运行一段时间，这样我们才能捕捉和操作这个工作</li><li>放入后台执行的命令不能和前台用户有交互或需要前台输入，否则放入后台只能暂停，而不能执行</li></ul><h3 id="把进程放入后台" tabindex="-1">把进程放入后台 <a class="header-anchor" href="#把进程放入后台" aria-label="Permalink to &quot;把进程放入后台&quot;">​</a></h3><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#6F42C1;">tar</span><span style="color:#005CC5;"> -zcf</span><span style="color:#032F62;"> etx.tar.gz/etc</span><span style="color:#24292E;"> &amp;</span></span>
<span class="line"><span style="color:#6A737D;"># 在命令末尾加 \`&amp;\` 符号，把命令放入后台，并在后台执行</span></span>
<span class="line"></span>
<span class="line"><span style="color:#6F42C1;">ctrl+z</span></span>
<span class="line"><span style="color:#6A737D;"># 按下ctrl+z快捷键，进程会放在后台并且暂停</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h3 id="查看后台的进程" tabindex="-1">查看后台的进程 <a class="header-anchor" href="#查看后台的进程" aria-label="Permalink to &quot;查看后台的进程&quot;">​</a></h3><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#005CC5;">jobs</span><span style="color:#24292E;"> [-l]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>选项：</p><ul><li><code>-l</code> 显示工作的PID</li></ul><div class="warning custom-block"><p class="custom-block-title">注意</p><p>注： <code>+</code> 号代表最近一个放入后台的工作，也是工作恢复是，默认恢复的工作。<code>-</code> 号代表倒数第二个放入后台的工作</p></div><h3 id="将后台暂停的工作恢复到前台" tabindex="-1">将后台暂停的工作恢复到前台 <a class="header-anchor" href="#将后台暂停的工作恢复到前台" aria-label="Permalink to &quot;将后台暂停的工作恢复到前台&quot;">​</a></h3><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#005CC5;">fg</span><span style="color:#032F62;"> %工作号</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>参数：</p><ul><li><code>%工作号</code> %号可以省略，但是注意工作号和PID的区别</li></ul><h3 id="把后台暂停的工作恢复到后台执行" tabindex="-1">把后台暂停的工作恢复到后台执行 <a class="header-anchor" href="#把后台暂停的工作恢复到后台执行" aria-label="Permalink to &quot;把后台暂停的工作恢复到后台执行&quot;">​</a></h3><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#005CC5;">bg</span><span style="color:#032F62;"> %工作号</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><div class="warning custom-block"><p class="custom-block-title">注意</p><p>注：后台恢复执行的命令，是不能和前台有交互的，否则不能恢复到后台执行</p></div>`,62)])])}const h=e(n,[["render",i]]);export{b as __pageData,h as default};
